-- ----------------------------------------------------------------------------
-- vw_edb_relations: The R0 spec's extensional database relations (r0/spec.json's 'edb' map): the fixed vocabulary every rule and command is built from.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_edb_relations CASCADE;
CREATE VIEW vw_edb_relations WITH (security_invoker = ON) AS
SELECT
  t.relation_id,                                                                -- Stored identity: the EDB relation name from r0/spec.json's edb map (e.g. 'Warehouse').
  t.fields,                                                                     -- JSON array of the relation's field names, verbatim from spec.json (e.g. '["id"]').
  t.field_count,                                                                -- Number of fields, counted once at transcription time.
  t.description,                                                                -- What this EDB relation models in the warehouse-network domain.
  calc_edb_relations_name(t.relation_id) AS name,                               -- Display alias.
  t.seed_facts,                                                                 -- h0 seed facts whose Relation is this EDB relation.
  t.transition_effects                                                          -- Transition effects that assert/retract into this relation.
FROM edb_relations t;

-- ----------------------------------------------------------------------------
-- vw_commands: The R0 spec's commands (r0/spec.json's 'commands' map): the only way an input history can act on the state.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_commands CASCADE;
CREATE VIEW vw_commands WITH (security_invoker = ON) AS
SELECT
  t.command_id,                                                                 -- Stored identity: the command name from r0/spec.json's commands map (e.g. 'AddRoute').
  t.params,                                                                     -- JSON array of the command's parameter names, verbatim from spec.json.
  t.param_count,                                                                -- Number of parameters, counted once at transcription time.
  t.description,                                                                -- What issuing this command means in the warehouse-network domain.
  calc_commands_name(t.command_id) AS name,                                     -- Display alias.
  t.transitions                                                                 -- Transitions this command can fire.
FROM commands t;

-- ----------------------------------------------------------------------------
-- vw_rules: Every stratified Datalog-with-negation-and-aggregation rule in the R0 spec (r0/spec.json's 'rules' array), including guard/effect/event rules for transitions and the two integrity-constraint rules.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rules CASCADE;
CREATE VIEW vw_rules WITH (security_invoker = ON) AS
SELECT
  t.rule_id,                                                                    -- Stored identity: the rule's 'id' in r0/spec.json's rules array (e.g. 'reach_base').
  t.head_predicate,                                                             -- The rule's head predicate name (head[0] in spec.json), e.g. 'Reachable'.
  t.kind,                                                                       -- 'rule' for a body-clause rule, 'aggregation' for an agg-clause rule (spec.json's 'agg' key).
  t.head_json,                                                                  -- The rule's head tuple, verbatim JSON from spec.json.
  t.body_json,                                                                  -- The rule's body clause list, verbatim JSON from spec.json (null for aggregation rules).
  t.agg_json,                                                                   -- The rule's agg clause, verbatim JSON from spec.json (null for body rules).
  t.paper_section_ref,                                                          -- CMCC-Core Representation Theorem section(s) this rule exercises.
  t.description,                                                                -- What the rule computes and, for reflection.py, which G_R node it constructs.
  calc_rules_name(t.rule_id) AS name,                                           -- Display alias.
  t.guarded_transitions,                                                        -- Transitions whose Guard is this rule.
  t.transition_effects,                                                         -- Transition effects whose FromRule is this rule.
  t.transition_events,                                                          -- Transition events whose FromRule is this rule.
  t.integrity_constraints                                                       -- Integrity constraints whose Rule is this rule.
FROM rules t;

-- ----------------------------------------------------------------------------
-- vw_transitions: The R0 spec's transitions (r0/spec.json's 'transitions' array): command + guard pairs that may fire, each with its effects and events.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_transitions CASCADE;
CREATE VIEW vw_transitions WITH (security_invoker = ON) AS
SELECT
  t.transition_id,                                                              -- Stored identity: the transition's 'name' in r0/spec.json's transitions array (e.g. 'AddRoute').
  t.command,                                                                    -- The command that can fire this transition.
  t.guard,                                                                      -- The rule whose head predicate gates this transition.
  t.description,                                                                -- What this transition does when its guard is satisfied.
  calc_transitions_name(t.transition_id) AS name,                               -- Display alias.
  t.effects,                                                                    -- This transition's ordered assert/retract effects.
  t.events                                                                      -- This transition's emitted events.
FROM transitions t;

-- ----------------------------------------------------------------------------
-- vw_transition_effects: One row per (transition, effect) pair: an ordered assert/retract of a rule's derived tuples into an EDB relation.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_transition_effects CASCADE;
CREATE VIEW vw_transition_effects WITH (security_invoker = ON) AS
SELECT
  t.effect_id,                                                                  -- Stored identity: '<TransitionId>#effect<index>', ordered as in spec.json.
  t.transition,                                                                 -- The transition this effect belongs to.
  t.op,                                                                         -- 'assert' or 'retract'.
  t.relation,                                                                   -- The EDB relation this effect asserts into or retracts from.
  t.from_rule,                                                                  -- The rule whose derived tuples this effect applies.
  calc_transition_effects_name(t.effect_id) AS name                             -- Display alias.
FROM transition_effects t;

-- ----------------------------------------------------------------------------
-- vw_transition_events: One row per (transition, event) pair: an event relation emitted when the transition fires.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_transition_events CASCADE;
CREATE VIEW vw_transition_events WITH (security_invoker = ON) AS
SELECT
  t.event_id,                                                                   -- Stored identity: '<TransitionId>#event<index>', ordered as in spec.json.
  t.transition,                                                                 -- The transition this event belongs to.
  t.event_relation,                                                             -- The event relation name emitted (e.g. 'RouteAdded'); not an EDB relation.
  t.from_rule,                                                                  -- The rule whose derived tuples produce this event.
  calc_transition_events_name(t.event_id) AS name                               -- Display alias.
FROM transition_events t;

-- ----------------------------------------------------------------------------
-- vw_integrity_constraints: The R0 spec's integrity constraints (r0/spec.json's 'constraints' array): predicates whose nonempty derivation rejects a transition. Named IntegrityConstraints, not Constraints -- rulebook-to-rulespeak v2026.09.17.2011 treats a table literally named 'Constraints' as a reserved word and fails the whole build with "Entity '' does not resolve to any table."
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_integrity_constraints CASCADE;
CREATE VIEW vw_integrity_constraints WITH (security_invoker = ON) AS
SELECT
  t.constraint_id,                                                              -- Stored identity: the constraint's head predicate name, verbatim from spec.json's constraints array (e.g. 'NegativeCap').
  t.rule,                                                                       -- The rule that derives this constraint's violations.
  t.description,                                                                -- What a nonempty derivation of this predicate means, and which transition it rejects.
  calc_integrity_constraints_name(t.constraint_id) AS name                      -- Display alias.
FROM integrity_constraints t;

