-- ----------------------------------------------------------------------------
-- vw_reflection_conditions: The six conditions of constructor reflection, section 13 of the paper.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_reflection_conditions CASCADE;
CREATE VIEW vw_reflection_conditions WITH (security_invoker = ON) AS
SELECT
  t.condition_id,                                                               -- Stored identity, matching conformance/matrix.json's condition keys (e.g. '1_constructor_preservation').
  t.condition_number,                                                           -- The condition's number in §13 (1-6).
  t.title,                                                                      -- Short name of the condition.
  t.paper_section_ref,                                                          -- Paper section this condition is defined in.
  t.description,                                                                -- What the condition checks on the substrate artifact's call graph.
  calc_reflection_conditions_name(t.condition_id) AS name,                      -- Display alias.
  t.reflection_results                                                          -- Per-substrate pass/fail/delegated outcomes for this condition.
FROM reflection_conditions t;

-- ----------------------------------------------------------------------------
-- vw_substrates: The three substrates checked against the R0 spec: transparent (the real representation) and two controls, tangled and interpreter, that are expected to fail reflection on purpose.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_substrates CASCADE;
CREATE VIEW vw_substrates WITH (security_invoker = ON) AS
SELECT
  t.substrate_id,                                                               -- Stored identity, matching conformance/matrix.json's substrate keys.
  t.description,                                                                -- What this substrate is and how it is generated.
  t.paper_section_ref,                                                          -- Paper section(s) this substrate demonstrates.
  t.is_control,                                                                 -- True for the two substrates that are deliberately expected to fail reflection (tangled, interpreter).
  calc_substrates_name(t.substrate_id) AS name,                                 -- Display alias.
  t.answer_key_results,                                                         -- This substrate's per-input-history answer-key results.
  t.reflection_results,                                                         -- This substrate's per-condition reflection results.
  calc_substrates_answer_key_result_count(t.substrate_id) AS answer_key_result_count,-- Number of answer-key results recorded for this substrate.
  calc_substrates_answer_key_fail_count(t.substrate_id) AS answer_key_fail_count,-- Number of answer-key results recorded as a failure for this substrate.
  calc_substrates_answer_key_ok(t.substrate_id) AS answer_key_ok,               -- True when every recorded answer-key result for this substrate passed (§11).
  calc_substrates_reflection_result_count(t.substrate_id) AS reflection_result_count,-- Number of reflection results recorded for this substrate.
  calc_substrates_reflection_fail_count(t.substrate_id) AS reflection_fail_count,-- Number of reflection conditions recorded as a failure for this substrate.
  calc_substrates_reflection_ok(t.substrate_id) AS reflection_ok,               -- True when no recorded reflection condition failed for this substrate (§13). Delegated conditions never count as a failure.
  calc_substrates_conformant(t.substrate_id) AS conformant                      -- True only when this substrate passes both gates: the answer key and reflection.
FROM substrates t;

-- ----------------------------------------------------------------------------
-- vw_answer_key_results: Per (substrate, input history) answer-key outcomes, ingested from a fresh run of conformance/run.py (conformance/matrix.json). Witnessed data, never recomputed here.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_answer_key_results CASCADE;
CREATE VIEW vw_answer_key_results WITH (security_invoker = ON) AS
SELECT
  t.answer_key_result_id,                                                       -- Stored identity: '<SubstrateId>__<InputHistoryId>'.
  t.substrate,                                                                  -- The substrate this result was computed for.
  t.input_history,                                                              -- The input history this result was computed against.
  t.traces_produced,                                                            -- Number of distinct traces this substrate produced for this input history (witnessed by conformance/run.py).
  t.permitted,                                                                  -- Size of the permitted (expected) trace set for this input history (witnessed by tools/gen_expected.py).
  t.outcome,                                                                    -- 'pass' if every produced trace was inside the permitted set, else 'fail'. Witnessed by conformance/run.py; never recomputed here.
  calc_answer_key_results_name(t.answer_key_result_id) AS name                  -- Display alias.
FROM answer_key_results t;

-- ----------------------------------------------------------------------------
-- vw_reflection_results: Per (substrate, reflection condition) outcomes, ingested from a fresh run of conformance/run.py (conformance/matrix.json). Witnessed data, never recomputed here.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_reflection_results CASCADE;
CREATE VIEW vw_reflection_results WITH (security_invoker = ON) AS
SELECT
  t.reflection_result_id,                                                       -- Stored identity: '<SubstrateId>__<ConditionId>'.
  t.substrate,                                                                  -- The substrate this reflection outcome was computed for.
  t.reflection_condition,                                                       -- The §13 condition this outcome is for.
  t.outcome,                                                                    -- 'pass', 'fail' or 'delegated' (condition 4 is always delegated to the answer key by design). Witnessed by tools/reflection_check.py; never recomputed here.
  calc_reflection_results_name(t.reflection_result_id) AS name                  -- Display alias.
FROM reflection_results t;

